codeExamples.raw:
curl  -X POST \
      'https://developer.api.autodesk.com/modelderivative/v2/designdata/job' \
      -H 'Content-Type: application/json' \
      -H 'Authorization: Bearer <YOUR_ACCESS_TOKEN>' \
      -H 'x-ads-force: true' \
      -d '{
          "input": {
              "urn": "<BASE64_ENCODED_URN_OF_SOURCE_FILE>",
          },
          "output": {
              "formats": [
                  {
                      "type": "svf2",
                      "views": [
                          "2d",
                          "3d"
                      ],
                     "advanced": {
                       "generateMasterViews": true
                     }
                  }
              ]
          }
      }'
